'use client'
import React, { useEffect, useRef } from 'react'
import gsap from 'gsap'
import { BasePhaseProps } from '@/lib/types'
import WantedStarsHUD from './WantedStarsHUD'

export default function WarningScreen({ onComplete, sounds }: BasePhaseProps) {
    const cardRef = useRef<HTMLDivElement | null>(null)
    const flashRef = useRef<HTMLDivElement | null>(null)

    useEffect(() => {
        let triggered = false

        if (cardRef.current) {
            gsap.fromTo(
                cardRef.current,
                { opacity: 0, y: 20, scale: 0.98 },
                { opacity: 1, y: 0, scale: 1, duration: 1.0, ease: 'power3.out' }
            )
        }

        const proceed = () => {
            if (triggered) return
            triggered = true

            try {
                if (sounds?.warningAccept) {
                    sounds.warningAccept.play()
                }
                if (sounds?.ambience) {
                    sounds.ambience.loop(true)
                    sounds.ambience.play()
                }
            } catch (e) {
                console.warn('Audio notice in warning screen:', e)
            }

            if (flashRef.current) {
                gsap.to(flashRef.current, {
                    opacity: 1,
                    duration: 0.12,
                    ease: 'power2.in',
                    onComplete: () => {
                        if (flashRef.current) {
                            gsap.to(flashRef.current, {
                                opacity: 0,
                                duration: 0.25,
                                ease: 'power2.out',
                                onComplete,
                            })
                        } else {
                            onComplete()
                        }
                    },
                })
            } else {
                onComplete()
            }
        }

        const handleKey = (e: KeyboardEvent) => {
            if (e.key === 'Enter' || e.key === ' ' || e.key === 'Escape') {
                proceed()
            }
        }

        const handleClick = () => {
            proceed()
        }

        document.addEventListener('keydown', handleKey)
        document.addEventListener('click', handleClick)

        return () => {
            document.removeEventListener('keydown', handleKey)
            document.removeEventListener('click', handleClick)
            if (cardRef.current) gsap.killTweensOf(cardRef.current)
            if (flashRef.current) gsap.killTweensOf(flashRef.current)
        }
    }, [onComplete, sounds])

    return (
        <div
            style={{
                position: 'fixed',
                inset: 0,
                background: '#000',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                zIndex: 100,
                cursor: 'pointer',
                userSelect: 'none',
            }}
        >
            <div className="noise-overlay" />
            <div className="crt-scanlines" />

            {/* Top HUD with Wanted Stars */}
            <div
                style={{
                    position: 'absolute',
                    top: 32,
                    left: 40,
                    right: 40,
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    zIndex: 120,
                }}
            >
                <div
                    style={{
                        fontFamily: 'ChaletComprime1960, "Barlow Condensed", sans-serif',
                        fontSize: '0.85rem',
                        letterSpacing: '0.25em',
                        color: 'rgba(255,255,255,0.6)',
                        textTransform: 'uppercase',
                    }}
                >
                    ROCKSTAR PROTOCOL // SAN ANDREAS
                </div>
                <WantedStarsHUD count={5} size={18} />
            </div>

            <div
                ref={cardRef}
                style={{
                    maxWidth: 780,
                    textAlign: 'center',
                    padding: '40px 30px',
                    zIndex: 110,
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                    gap: '24px',
                }}
            >
                <div
                    style={{
                        display: 'inline-block',
                        background: 'rgba(245, 166, 35, 0.15)',
                        border: '1px solid rgba(245, 166, 35, 0.5)',
                        padding: '4px 18px',
                        fontFamily: 'ChaletComprime1960, "Barlow Condensed", sans-serif',
                        fontSize: '0.85rem',
                        letterSpacing: '0.35em',
                        color: '#f5a623',
                        textTransform: 'uppercase',
                    }}
                >
                    CONTENT ADVISORY // GTA V INTERACTIVE PROTOCOL
                </div>

                <p
                    style={{
                        fontFamily: 'ChaletComprime1960, "Barlow Condensed", sans-serif',
                        fontSize: 'clamp(0.95rem, 2.2vw, 1.25rem)',
                        letterSpacing: '0.22em',
                        lineHeight: 1.8,
                        color: 'rgba(255,255,255,0.9)',
                        textTransform: 'uppercase',
                        maxWidth: '680px',
                    }}
                >
                    THIS IS A FICTIONAL INTERACTIVE DEVELOPER PORTFOLIO
                    <br />
                    DESIGNED WITH CINEMATIC OPEN-WORLD GAMEPLAY PROTOCOLS
                </p>

                <div
                    className="smooth-pulse"
                    style={{
                        marginTop: '16px',
                        display: 'flex',
                        alignItems: 'center',
                        gap: '12px',
                    }}
                >
                    <span
                        style={{
                            fontFamily: 'ChaletLondon1960, "Bebas Neue", Montserrat, sans-serif',
                            fontSize: 'clamp(1.1rem, 2.6vw, 1.45rem)',
                            letterSpacing: '0.28em',
                            textTransform: 'uppercase',
                            color: '#ffffff',
                        }}
                    >
                        PRESS ENTER OR CLICK TO CONTINUE
                    </span>
                </div>
            </div>

            <div
                ref={flashRef}
                style={{
                    position: 'absolute',
                    inset: 0,
                    background: '#ffffff',
                    opacity: 0,
                    pointerEvents: 'none',
                    zIndex: 200,
                }}
            />
        </div>
    )
}
